package com.citacloud.app.views;
import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.*; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.datetimepicker.DateTimePicker; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.time.LocalDateTime; import java.util.*;
@Route(value="recordatorios",layout=MainLayout.class) @PageTitle("Recordatorios | CitaCloud") @PermitAll public class RecordatoriosView extends VerticalLayout { final RecordatorioService service;final CitaService citas;final UUID empresa;final Grid<RecordatorioCita> grid=new Grid<>(RecordatorioCita.class,false);
 public RecordatoriosView(RecordatorioService s,CitaService c){service=s;citas=c;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);Button nuevo=new Button("Nuevo recordatorio",e->dialogo());add(new HorizontalLayout(new H2("Recordatorios"),nuevo),new Paragraph("Programe avisos por correo o notificación interna."));grid.addColumn(r->r.getCita().getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(RecordatorioCita::getCanal).setHeader("CANAL");grid.addColumn(RecordatorioCita::getFechaProgramada).setHeader("PROGRAMADO");grid.addColumn(RecordatorioCita::getEstado).setHeader("ESTADO");grid.setWidthFull();add(grid);cargar();}void cargar(){grid.setItems(empresa==null?List.of():service.listar(empresa));} void dialogo(){if(empresa==null)return;Dialog d=new Dialog();ComboBox<Cita> cita=new ComboBox<>("Cita",citas.listarPorEmpresa(empresa));cita.setItemLabelGenerator(x->x.getPaciente().getNombreCompleto()+" · "+x.getFecha());ComboBox<String> canal=new ComboBox<>("Canal",List.of("CORREO","INTERNA"));DateTimePicker fecha=new DateTimePicker("Fecha programada");fecha.setValue(LocalDateTime.now().plusDays(1));Button guardar=new Button("Guardar",e->{try{service.crear(empresa,cita.getValue().getId(),canal.getValue(),fecha.getValue());d.close();cargar();Notification.show("Recordatorio programado correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new VerticalLayout(cita,canal,fecha,guardar));d.open();}}
